import type { Lang } from "./i18n";

export type StoreItemId = string;
export type StoreItemCategory = "card_back" | "avatar" | "effect" | "title" | "frame" | "emote" | "table_design" | "card_design" | "logo_stinger";

export type LocalizedText = Partial<Record<Lang, string>>;

interface StoreItemBase {
  id: StoreItemId;
  category: StoreItemCategory;
  price: number;
  preview: string;
  previewColor: string;
  rarity: "common" | "rare" | "epic" | "legendary";
  isDefault?: boolean;
  backColors?: string[];
  backAccent?: string;
  backPattern?: "diamonds" | "stars" | "circles" | "crosses" | "waves" | "hexagons";
  animated?: boolean;
}

export interface StoreItem extends StoreItemBase {
  name: LocalizedText;
  description: LocalizedText;
}

export interface StoreItemRaw extends StoreItemBase {
  name: string;
  description: string;
}

export type LocalizedStoreItem = StoreItemBase & {
  name: string;
  description: string;
};

